CREATE TABLE learning_paths (path_id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', state TEXT NOT NULL CHECK(state IN ('draft','published','archived')), revision INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE learning_units (unit_id TEXT PRIMARY KEY, path_id TEXT NOT NULL REFERENCES learning_paths(path_id) ON DELETE CASCADE, title TEXT NOT NULL, ordinal INTEGER NOT NULL, UNIQUE(path_id,ordinal));
CREATE TABLE learning_lessons (lesson_id TEXT PRIMARY KEY, unit_id TEXT NOT NULL REFERENCES learning_units(unit_id) ON DELETE CASCADE, title TEXT NOT NULL, active_version INTEGER, created_at TEXT NOT NULL);
CREATE TABLE lesson_versions (lesson_id TEXT NOT NULL REFERENCES learning_lessons(lesson_id) ON DELETE CASCADE, version INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('draft','published')), rules_version TEXT NOT NULL, published_at TEXT, created_at TEXT NOT NULL, PRIMARY KEY(lesson_id,version));
CREATE TRIGGER lesson_versions_immutable_update BEFORE UPDATE ON lesson_versions WHEN OLD.state='published' BEGIN SELECT RAISE(ABORT,'published lesson version is immutable'); END;
CREATE TRIGGER lesson_versions_immutable_delete BEFORE DELETE ON lesson_versions WHEN OLD.state='published' BEGIN SELECT RAISE(ABORT,'published lesson version is immutable'); END;
CREATE TABLE lesson_steps (lesson_id TEXT NOT NULL, version INTEGER NOT NULL, step_id TEXT NOT NULL, kind TEXT NOT NULL, ordinal INTEGER NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(lesson_id,version,step_id), UNIQUE(lesson_id,version,ordinal), FOREIGN KEY(lesson_id,version) REFERENCES lesson_versions(lesson_id,version) ON DELETE CASCADE);
CREATE TRIGGER published_steps_no_insert BEFORE INSERT ON lesson_steps WHEN (SELECT state FROM lesson_versions WHERE lesson_id=NEW.lesson_id AND version=NEW.version)='published' BEGIN SELECT RAISE(ABORT,'published lesson steps are immutable'); END;
CREATE TRIGGER published_steps_no_update BEFORE UPDATE ON lesson_steps WHEN (SELECT state FROM lesson_versions WHERE lesson_id=OLD.lesson_id AND version=OLD.version)='published' BEGIN SELECT RAISE(ABORT,'published lesson steps are immutable'); END;
CREATE TRIGGER published_steps_no_delete BEFORE DELETE ON lesson_steps WHEN (SELECT state FROM lesson_versions WHERE lesson_id=OLD.lesson_id AND version=OLD.version)='published' BEGIN SELECT RAISE(ABORT,'published lesson steps are immutable'); END;
CREATE TABLE practice_attempts (attempt_id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES accounts(actor_id), mission_id TEXT NOT NULL, prompt_version TEXT NOT NULL, status TEXT NOT NULL, measurements TEXT NOT NULL DEFAULT '{}', evidence TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX practice_attempts_owner_idx ON practice_attempts(owner_id,created_at);
CREATE TABLE step_attempts (attempt_id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES accounts(actor_id), lesson_id TEXT NOT NULL, lesson_version INTEGER NOT NULL, step_id TEXT NOT NULL, rules_version TEXT NOT NULL, status TEXT NOT NULL, measurements TEXT NOT NULL DEFAULT '{}', evidence TEXT NOT NULL DEFAULT '{}', teacher_override TEXT, revision INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, FOREIGN KEY(lesson_id,lesson_version,step_id) REFERENCES lesson_steps(lesson_id,version,step_id));
CREATE INDEX step_attempts_owner_idx ON step_attempts(owner_id,created_at);
CREATE TABLE review_items (review_id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES accounts(actor_id), source_attempt TEXT NOT NULL REFERENCES practice_attempts(attempt_id) ON DELETE CASCADE, content_key TEXT NOT NULL, box INTEGER NOT NULL DEFAULT 0, due_at TEXT NOT NULL, state TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(owner_id,source_attempt,content_key));
CREATE INDEX review_items_due_idx ON review_items(owner_id,state,due_at);
CREATE TABLE achievements (owner_id TEXT NOT NULL REFERENCES accounts(actor_id), code TEXT NOT NULL, unlocked_at TEXT NOT NULL, seen_at TEXT, PRIMARY KEY(owner_id,code));
CREATE TABLE streak_days (owner_id TEXT NOT NULL REFERENCES accounts(actor_id), local_date TEXT NOT NULL, effort_count INTEGER NOT NULL CHECK(effort_count>=0), PRIMARY KEY(owner_id,local_date));
CREATE TABLE learning_media (media_id TEXT PRIMARY KEY, lesson_id TEXT NOT NULL REFERENCES learning_lessons(lesson_id), media_kind TEXT NOT NULL, blob_id TEXT, sha256 TEXT, size_bytes INTEGER, created_at TEXT NOT NULL);
